387	function syncClientItems(progress: number): void {
388	  const shouldShow = progress >= CLIENT_REVEAL_START && progress < CLIENT_REVEAL_END;
389	  if (mainSceneDomState.isClientItemsVisible === shouldShow) return;
390	  const items = getClientItems();
391	  if (items.length === 0) return;
392	  mainSceneDomState.isClientItemsVisible = shouldShow;
393	  mainSceneDomState.clientItemTimers = clearTimers(mainSceneDomState.clientItemTimers);
394	  const queue = shouldShow ? items : items.slice().reverse();
395	  queue.forEach((item, index) => {
396	    const timerId = window.setTimeout(
397	      () => {
398	        item.classList.add(INIT_DOM_CLASSES.blockBase);
399	        item.classList.remove(INIT_DOM_CLASSES.boxHidden);
400	        item.classList.remove("is-block-reveal-down");
401	        if (shouldShow) {
