403	          return;
404	        }
405	        item.classList.remove(INIT_DOM_CLASSES.blockUp);
406	        item.classList.add("is-block-reveal-down");
407	      },
408	      index * CLIENT_REVEAL_STAGGER_SECONDS * 1000,
409	    );
410	    mainSceneDomState.clientItemTimers.push(timerId);
411	  });
412	}
