185	  private async _init(): Promise<void> {
186	    await TheatreStudioService.ensureReady(CONTACT_PAGE_TYPE);
187	    TheatreStudioService.restoreUi();
188	    const savedState = this._readStateSource();
189	    const project = TheatreProjectSession.open<
190	      ContactTheatreValue,
191	      ContactTheatreProps
192	    >(
193	      CONTACT_THEATRE_PROJECT_ID,
194	      {
195	        state: savedState ?? undefined,
196	      },
197	    );
198	    await project.ready;
199	    CONTACT_THEATRE_SHEET_IDS.forEach((sheetId) => {
200	      const sheet = TheatreSheetSession.open(project, sheetId);
201	      const object = sheet.object(
202	        CONTACT_THEATRE_OBJECT_ID,
203	        this._readSceneValues(),
204	        { reconfigure: true },
205	      );
206	      this._sheetById.set(sheetId, sheet);
207	      this._objectBySheetId.set(sheetId, object);
208	      this._sequenceBySheetId.set(sheetId, TheatreSequenceSession.get(sheet));
209	    });
210	    this._attachSheet(PRIMARY_SHEET_ID);
211	    this._bindControls();
212	    this._unsubscribeSelection = TheatreStudioService.bindSelectionChange(
213	      (selection) => {
214	        this._syncAuthorSheetFromStudioSelection(selection);
215	      },
216	    );
217	    this._renderSheetSelector();
218	    this._renderMatchPrevButton();
219	    this._renderExportButton();
220	    this._renderStatus(
221	      savedState ? "CONTACT SAVEFILE LOADED" : "CONTACT THEATRE READY",
