227	  private _attachSheet(sheetId: ContactTheatreSheetId): void {
228	    const sheet = this._sheetById.get(sheetId);
229	    const object = this._objectBySheetId.get(sheetId);
230	    if (!sheet || !object) return;
231	    this._unsubscribeValues?.();
232	    this._authorSheetId = sheetId;
233	    this._unsubscribeValues = TheatrePlaybackService.bindValues(
234	      object,
235	      (values: ContactTheatreValue) => {
236	        this._rig.apply(this._engine, values);
237	        this._syncControlsToCameraState();
238	      },
239	    );
240	    this._syncStudioSelection(sheet, object);
241	    this._renderStatus(`ACTIVE SHEET ${sheetId.toUpperCase()}`);
242	  }
