244	  private _syncStudioSelection(
245	    sheet: TheatreSheetPort<ContactTheatreValue, ContactTheatreProps>,
246	    object: ContactTheatreObject,
247	  ): void {
248	    this._syncingStudioSelection = true;
249	    try {
250	      TheatreStudioService.setSelection([sheet, object]);
251	    } finally {
252	      this._syncingStudioSelection = false;
253	    }
254	  }
255	
256	  private _syncAuthorSheetFromStudioSelection(
257	    selection: TheatreSelectionItemPort[],
258	  ): void {
259	    if (this._syncingStudioSelection) return;
260	    const nextSheetId = this._findSelectedSheetId(selection);
261	    if (!nextSheetId) return;
262	    if (nextSheetId === this._authorSheetId) return;
263	    this._attachSheet(nextSheetId);
264	    this._syncSheetSelector();
265	    this._renderStatus(`ACTIVE SHEET ${nextSheetId.toUpperCase()}`);
266	  }
267	
268	  private _findSelectedSheetId(
269	    selection: TheatreSelectionItemPort[],
270	  ): ContactTheatreSheetId | null {
271	    for (const [sheetId, sheet] of this._sheetById.entries()) {
272	      if (selection.includes(sheet)) return sheetId;
273	    }
274	    for (const [sheetId, object] of this._objectBySheetId.entries()) {
275	      if (selection.includes(object)) return sheetId;
276	    }
277	    return null;
278	  }
