303	  private _recordFrame(force = false): void {
304	    if (!force && !this._sampling) return;
305	    const object = this._objectBySheetId.get(this._authorSheetId);
306	    const scrub = this._recordScrub;
307	    if (!object || !scrub) return;
308	    const now = performance.now();
309	    if (!force && now - this._lastSampleAt < FRAME_MS) return;
310	    this._lastSampleAt = now;
311	    const values = this._readCameraValues();
312	    const cameraScrub = scrub as unknown as ContactTheatreScrubCameraPort;
313	    cameraScrub.capture(({ set }) => {
314	      set(
315	        object.props.camera as ContactCameraTheatreProps["camera"],
316	        values.camera as ContactCameraTheatreValue["camera"],
317	      );
318	    });
319	  }
