336	  private _matchFromPrevious(): void {
337	    const authorSheetIds =
338	      CONTACT_THEATRE_SHEET_IDS as readonly ContactTheatreSheetId[];
339	    const currentIndex = authorSheetIds.indexOf(this._authorSheetId);
340	    if (currentIndex <= 0) {
341	      this._renderStatus("NO PREVIOUS SHEET");
342	      return;
343	    }
344	    const previousSheetId = authorSheetIds[currentIndex - 1];
345	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
346	    const previousSequence = this._sequenceBySheetId.get(previousSheetId) ?? null;
347	    const currentObject = this._currentObject;
348	    const currentSequence = this._currentSequence;
349	    if (!previousObject || !previousSequence || !currentObject || !currentSequence) {
350	      this._renderStatus("MATCH FAILED");
351	      return;
352	    }
353	
354	    const previousEndValues = this._readSheetEndValues(
355	      previousSheetId,
356	      previousObject,
357	      previousSequence,
358	    );
359	    if (!previousEndValues) {
360	      this._renderStatus("MATCH FAILED");
361	      return;
362	    }
363	
364	    currentObject.initialValue = previousEndValues;
365	    this._writeMatchStartKeyframe(
366	      currentObject,
367	      currentSequence,
368	      previousEndValues,
369	    );
370	    this._rig.apply(this._engine, previousEndValues);
371	    this._syncControlsToCameraState();
372	    this._persistSaveFileSnapshot("MATCH SAVE FAILED");
373	    this._renderStatus(`MATCHED ${previousSheetId.toUpperCase()}`);
374	  }
